/*
 * A278569  Numbers of the form p^i*q^j*r^k where p,q,r are distinct odd
 *          primes and i,j,k >= 1.
 * https://oeis.org/A278569
 *
 * Offset:    1    (a(1) is the first term)
 * Keywords:  nonn
 * Formula:   not stated
 * Range:     u8 n <= 5, u16 n <= 9528, u32 n <= 10000, u64 n <= 10000,
 *            u128 n <= 10000, big any n
 * Helpers:   none
 *
 * Sequence data from the OEIS (https://oeis.org), licensed CC BY-SA 4.0.
 */

/* Generated by iterating over odd integers and selecting those of the
   form p^i*q^j*r^k with p,q,r distinct odd primes and i,j,k>=1.
   The algorithm builds a sieve of smallest prime factors up to a fixed
   bound and keeps a static cache of found values.  The function works
   for all n≥1 regardless of the order of calls. */
#include <stddef.h>
#include <stdint.h>
#include <stdbool.h>
#include <stdlib.h>

/* Set a sieve limit that covers the required range for n≈10000.
   This is large enough – the 10000‑th term is < 5·10⁶. */
static const idx_t SIEVE_LIMIT = 5000000;

static uint32_t *spf = NULL;     /* smallest prime factor array */
static idx_t   spf_limit = 0;

/*------------------------------------------------------------*/
/* initialise the SPF sieve                                   */
/*------------------------------------------------------------*/
static void init_spf(void)
{
    if (spf_limit >= SIEVE_LIMIT)          /* already ready */
        return;

    spf_limit = SIEVE_LIMIT;
    spf = (uint32_t *)calloc( (size_t)(spf_limit + 1), sizeof(uint32_t) );
    if (!spf) abort();

    for (idx_t i = 2; i <= spf_limit; ++i) {
        if (spf[i] == 0) {                 /* i is prime */
            spf[i] = (uint32_t)i;
            if (i * i <= spf_limit) {
                for (idx_t j = i * i; j <= spf_limit; j += i)
                    if (spf[j] == 0)
                        spf[j] = (uint32_t)i;
            }
        }
    }
}

/*------------------------------------------------------------*/
/* return true iff x has exactly three distinct odd primes   */
/* all exponents ≥1                                            */
/*------------------------------------------------------------*/
static bool has_three_odd_distinct_primes(uint64_t x)
{
    int distinct = 0;
    uint32_t prev = 0;

    while (x > 1) {
        uint32_t p = spf[(idx_t)x];
        if (p == 2)  /* even factor becomes disqualifier */
            return false;
        if (p != prev) {
            ++distinct;
            if (distinct > 3) return false;
            prev = p;
        }
        do /* skip all powers of p */ {
            x /= p;
        } while (x % p == 0);
    }
    return (distinct == 3);
}

/*------------------------------------------------------------*/
/* main sequence function                                     */
/*------------------------------------------------------------*/
seq_t a(idx_t n)
{
    /* static state for caching */
    static bool          spf_inited  = false;
    static seq_t        *cache       = NULL;
    static size_t        cache_cap   = 0;
    static size_t        cache_len   = 0;
    static uint64_t      next_candidate = 105; /* first odd number with 3 distinct odd primes */

    if (!spf_inited) {
        init_spf();
        spf_inited = true;
    }

    if (n == 0)                /* offset 1 – n should never be 0 */
        return 0;

    /* grow cache until it contains term n */
    while (cache_len < n) {
        uint64_t x = next_candidate;
        next_candidate += 2;   /* scan only odd numbers */

        /* simple safety guard – if needed we could extend the sieve */
        if (x > (uint64_t)spf_limit) abort();

        if (has_three_odd_distinct_primes(x)) {
            /* grow cache capacity if needed */
            if (cache_len == cache_cap) {
                size_t new_cap = cache_cap ? cache_cap * 2 : 64;
                seq_t *tmp = (seq_t *)realloc(cache, new_cap * sizeof(seq_t));
                if (!tmp) abort();
                cache      = tmp;
                cache_cap  = new_cap;
            }
            cache[cache_len++] = (seq_t)x;
        }
    }

    return cache[n - 1];
}
